package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math3.analysis.UnivariateRealFunction;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BrentSolver.solve method.
 * Aiming for high branch and line coverage.
 */
public class BrentSolver_solve_TriageGen2Test {

    private BrentSolver solver;
    private static final double EPSILON = 1e-14;

    @Before
    public void setUp() {
        solver = new BrentSolver();
    }

    /**
     * Test case where the initial guess is already a root.
     * Covers: Math.abs(yInitial) <= functionValueAccuracy branch.
     */
    @Test
    public void testSolve_InitialIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> x - 2.0;
        double min = 0.0;
        double max = 5.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(initial, result, EPSILON);
    }

    /**
     * Test case where the min endpoint is already a root.
     * Covers: Math.abs(yMin) <= functionValueAccuracy branch.
     */
    @Test
    public void testSolve_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> x;
        double min = 0.0;
        double max = 5.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(min, result, EPSILON);
    }

    /**
     * Test case where the max endpoint is already a root.
     * Covers: Math.abs(yMax) <= functionValueAccuracy branch.
     */
    @Test
    public void testSolve_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> x - 5.0;
        double min = 0.0;
        double max = 5.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(max, result, EPSILON);
    }

    /**
     * Test case where initial and min bracket the root.
     * Covers: yInitial - yMin < 0 branch.
     */
    @Test
    public void testSolve_InitialAndMinBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(min=0) = 1, f(initial=2) = -1 -> Root is between 0 and 2
        UnivariateRealFunction f = x -> 1.0 - x;
        double min = 0.0;
        double max = 5.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(1.0, result, 1e-7);
    }

    /**
     * Test case where initial and max bracket the root.
     * Covers: yInitial * yMax < 0 branch.
     */
    @Test
    public void testSolve_InitialAndMaxBracket() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(min=0) = 1, f(initial=2) = 1, f(max=5) = -1 -> Root is between 2 and 5
        UnivariateRealFunction f = x -> 3.0 - x;
        double min = 0.0;
        double max = 5.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(3.0, result, 1e-7);
    }

    /**
     * Test case where min and max have the same sign (No bracketing).
     * Covers: yMin * yMax > 0 branch (Throws IllegalArgumentException).
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_NoBracketing() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> x * x + 1; // Always positive
        double min = -1.0;
        double max = 1.0;
        double initial = 0.0;

        solver.solve(f, min, max, initial);
    }

    /**
     * Test case for the full Brent algorithm.
     * Covers: The final fallback solve(...) call.
     */
    @Test
    public void testSolve_FullBrent() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(0) = -1, f(5) = 1, f(2) = -0.5. Root is between 2 and 5.
        // This forces the logic through the final call.
        UnivariateRealFunction f = x -> x - 3.0;
        double min = 0.0;
        double max = 5.0;
        double initial = 2.0;

        double result = solver.solve(f, min, max, initial);
        assertEquals(3.0, result, 1e-7);
    }

    /**
     * Test case for invalid sequence (min > max or min > initial, etc).
     * Covers: verifySequence(min, initial, max) logic.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidSequence() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> x;
        // Depending on implementation of verifySequence, this should trigger error
        solver.solve(f, 5.0, 1.0, 3.0);
    }

    /**
     * Test case using Mockito to verify function evaluation behavior if needed.
     * This ensures the logic interacts with the function correctly.
     */
    @Test
    public void testSolve_FunctionCalls() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = mock(UnivariateRealFunction.class);
        // Simulate: f(initial) is root
        when(f.value(2.0)).thenReturn(0.0);

        double result = solver.solve(f, 0.0, 5.0, 2.0);
        assertEquals(2.0, result, EPSILON);
    }
}
